using System;
using System.IO;
using System.Linq;
using System.Collections.Generic;
using UnityEngine;
using UnityEditor;
using UnityEngine.SceneManagement;
using UnityEditor.SceneManagement;
using Object=UnityEngine.Object;

// Explicit replacement of the corridor's sheet cloth. Never runs on scene load.
public static class WorkerStrongholdMeshyPass
{
 const string ScenePath="Assets/Scenes/3D/RecoilFactoryInterior.unity";
 const string Folder="Assets/Recoil3D/WorkerStronghold/Meshy";
 const string Marker="Meshy volumetric bedding and hanging work clothes";
 const string MainRoot="Workers last refuge - corridor rebuild";
 const string Bed="Worker_pallet_bed_thick_mattress_wool_blanket-game-v2.glb";
 const string Clothes="Hanging_empty_canvas_worker_uniform_orange_trousers-game.glb";
 static T[] All<T>(Scene s)where T:Component{return s.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<T>(true)).ToArray();}
 static Transform G(string name,Transform parent,Vector3 position){var g=new GameObject(name).transform;g.SetParent(parent,false);g.position=position;return g;}
 static Bounds BoundsOf(Transform t){var rs=t.GetComponentsInChildren<Renderer>(true);if(rs.Length==0)throw new Exception("Model has no renderers: "+t.name);var b=rs[0].bounds;foreach(var r in rs)b.Encapsulate(r.bounds);return b;}
 static Transform Model(string file,Transform parent,string name){var prefab=AssetDatabase.LoadAssetAtPath<GameObject>(Folder+"/"+file);if(!prefab)throw new Exception("Missing optimized Meshy model "+file);var go=(GameObject)PrefabUtility.InstantiatePrefab(prefab,parent);go.name=name;foreach(var c in go.GetComponentsInChildren<Collider>(true))Object.DestroyImmediate(c);foreach(var c in go.GetComponentsInChildren<Collider2D>(true))Object.DestroyImmediate(c);return go.transform;}
 static Material Variant(Material source,string tag,Color tint){string path=Folder+"/Materials/"+tag+" "+source.name.Replace("/","-")+".mat";var m=AssetDatabase.LoadAssetAtPath<Material>(path);if(!m){m=new Material(source);AssetDatabase.CreateAsset(m,path);}foreach(string property in new[]{"_BaseColorFactor","_BaseColor","_Color"})if(m.HasProperty(property)){m.SetColor(property,source.GetColor(property)*tint);break;}m.enableInstancing=true;EditorUtility.SetDirty(m);return m;}
 static void Materials(Transform t,string tag,Color tint){foreach(var r in t.GetComponentsInChildren<Renderer>()){r.sharedMaterials=r.sharedMaterials.Select(m=>Variant(m,tag,tint)).ToArray();r.shadowCastingMode=UnityEngine.Rendering.ShadowCastingMode.On;r.receiveShadows=true;EditorUtility.SetDirty(r);}}
 static void RebuildBatches(Transform root){var batch=root.Find("Combined native detail - source parts retained editable");if(batch)Object.DestroyImmediate(batch.gameObject);foreach(var f in root.GetComponentsInChildren<MeshFilter>().Where(f=>f.GetComponent<MeshRenderer>()&&!PrefabUtility.IsPartOfPrefabInstance(f)&&!f.GetComponentInParent<ReadableProp>()))f.GetComponent<MeshRenderer>().enabled=true;typeof(WorkerStrongholdPass).GetMethod("Batch",System.Reflection.BindingFlags.Static|System.Reflection.BindingFlags.NonPublic).Invoke(null,new object[]{root});}
 public static string Apply(){if(EditorApplication.isPlayingOrWillChangePlaymode)throw new Exception("Stop play before editing");Directory.CreateDirectory(Folder+"/Materials");AssetDatabase.Refresh();var prev=SceneManager.GetActiveScene();var scene=SceneManager.GetSceneByPath(ScenePath);bool opened=!scene.isLoaded;if(opened)scene=EditorSceneManager.OpenScene(ScenePath,OpenSceneMode.Additive);try{var root=All<Transform>(scene).Single(t=>t.name==MainRoot);if(root.Find(Marker))return "Meshy replacement already present";string backup="Backups/FactoryWorkerBase/BeforeMeshyCloth-"+DateTime.Now.ToString("yyyyMMdd-HHmmss")+".unity";EditorSceneManager.SaveScene(scene,backup,true);var doors=All<RecoilDoor>(scene).Select(d=>EditorJsonUtility.ToJson(d)+d.transform.position).ToArray();var collisions=All<Collider2D>(scene).Select(c=>c.GetInstanceID()+"|"+c.bounds+"|"+c.enabled+"|"+c.gameObject.activeInHierarchy).ToArray();var npc=All<Transform>(scene).Single(t=>t.name=="Coaler cosplayer - resting on F2 bench");string npcState=EditorJsonUtility.ToJson(npc);var group=G(Marker,root,Vector3.zero);var report=new List<string>();
  var beds=root.GetComponentsInChildren<Transform>().Where(t=>t.name=="Pallet bed - abandoned wool bedding").ToArray();if(beds.Length!=3)throw new Exception("Expected 3 existing pallet beds");int index=0;foreach(var old in beds){var at=old.position;float yaw=old.eulerAngles.y;var model=Model(Bed,group,"Meshy pallet mattress wool blanket and pillow "+(++index));model.localRotation=Quaternion.identity;var b=BoundsOf(model);model.localScale=new Vector3(model.localScale.x*.86f/b.size.x,model.localScale.y*.52f/b.size.y,model.localScale.z*1.85f/b.size.z);model.rotation=Quaternion.Euler(0,yaw,0);b=BoundsOf(model);model.position+=at-new Vector3(b.center.x,b.min.y,b.center.z);Materials(model,"Pallet bedding",Color.white);old.gameObject.SetActive(false);EditorUtility.SetDirty(old.gameObject);b=BoundsOf(model);if(b.size.y<.12f)throw new Exception("Generated bedding has insufficient depth");report.Add(model.name+" size="+b.size.ToString("F3"));}
  var hanging=root.Find("F2 public rest area - restored hanging work clothes");var hooks=hanging.GetComponentsInChildren<Transform>().Where(t=>t.name=="Clothes hook").OrderBy(t=>t.position.x).ToArray();if(hooks.Length!=4)throw new Exception("Expected 4 existing laundry hooks");var yawOffsets=new[]{-9f,6f,-4f,10f};var tints=new[]{new Color(.95f,.96f,.90f),new Color(.82f,.87f,.81f),new Color(.96f,.89f,.79f),new Color(.89f,.92f,.85f)};for(int i=0;i<hooks.Length;i++){var model=Model(Clothes,group,"Meshy hanging empty canvas uniform "+(i+1));model.rotation=Quaternion.Euler(0,180+yawOffsets[i],0);var b=BoundsOf(model);model.localScale*=1.45f/b.size.y;b=BoundsOf(model);Vector3 top=hooks[i].position+new Vector3(0,-.02f,0);model.position+=top-new Vector3(b.center.x,b.max.y,b.center.z);Materials(model,"Workwear "+(i+1),tints[i]);b=BoundsOf(model);if(b.size.z<.06f)throw new Exception("Generated work clothes still too flat");report.Add(model.name+" size="+b.size.ToString("F3"));}
  foreach(var t in hanging.GetComponentsInChildren<Transform>(true).Where(t=>t.name=="Work shirt on hanging hook").ToArray()){t.gameObject.SetActive(false);EditorUtility.SetDirty(t.gameObject);}ConnectHangers(root);RebuildBatches(root);if(group.GetComponentsInChildren<Collider>(true).Length+group.GetComponentsInChildren<Collider2D>(true).Length!=0)throw new Exception("Detailed props add colliders");if(group.GetComponentsInChildren<Renderer>().Any(r=>r.bounds.min.z<1.05f))throw new Exception("Model enters player route");Physics2D.SyncTransforms();if(!doors.SequenceEqual(All<RecoilDoor>(scene).Select(d=>EditorJsonUtility.ToJson(d)+d.transform.position)))throw new Exception("Door state changed");if(!collisions.SequenceEqual(All<Collider2D>(scene).Select(c=>c.GetInstanceID()+"|"+c.bounds+"|"+c.enabled+"|"+c.gameObject.activeInHierarchy)))throw new Exception("Collision changed");if(npcState!=EditorJsonUtility.ToJson(npc))throw new Exception("Seated NPC moved");EditorSceneManager.MarkSceneDirty(scene);EditorSceneManager.SaveScene(scene);AssetDatabase.SaveAssets();report.Add("PASS: 3 beds and 4 outfits are fresh textured Meshy assets. Old flat clothing and bedding hidden; combined native meshes rebuilt, original rail/chains/hooks retained. No added colliders, route clear, doors and seated NPC unchanged. Backup="+backup);File.WriteAllLines("output/factory-worker-base/meshy-integration.txt",report);return string.Join("\n",report.ToArray());}finally{if(opened)EditorSceneManager.CloseScene(scene,true);SceneManager.SetActiveScene(prev);}}
 static void ConnectHangers(Transform root){var group=root.Find(Marker);if(group.Find("Visible metal links at hanging uniforms"))return;var links=G("Visible metal links at hanging uniforms",group,Vector3.zero);var hooks=root.Find("F2 public rest area - restored hanging work clothes").GetComponentsInChildren<Transform>().Where(t=>t.name=="Clothes hook").OrderBy(t=>t.position.x).ToArray();var models=group.Cast<Transform>().Where(t=>t.name.StartsWith("Meshy hanging empty canvas uniform")).OrderBy(t=>t.name).ToArray();for(int i=0;i<hooks.Length;i++){var b=BoundsOf(models[i]);var a=hooks[i].position+new Vector3(.05f,-.04f,0);var c=new Vector3(b.center.x,b.max.y-.1f,b.center.z);var mid=new Vector3(a.x,c.y, a.z);var points=new[]{a,mid,c};for(int j=0;j<2;j++){var go=GameObject.CreatePrimitive(PrimitiveType.Cylinder);go.name="Steel hanger connector";Object.DestroyImmediate(go.GetComponent<Collider>());go.transform.SetParent(links,true);go.transform.position=(points[j]+points[j+1])*.5f;go.transform.rotation=Quaternion.FromToRotation(Vector3.up,points[j+1]-points[j]);go.transform.localScale=new Vector3(.014f,(points[j+1]-points[j]).magnitude*.5f,.014f);go.GetComponent<Renderer>().sharedMaterial=hooks[i].GetComponent<Renderer>().sharedMaterial;}}}
 public static string FinishHangers(){var prev=SceneManager.GetActiveScene();var scene=SceneManager.GetSceneByPath(ScenePath);bool opened=!scene.isLoaded;if(opened)scene=EditorSceneManager.OpenScene(ScenePath,OpenSceneMode.Additive);try{ConnectHangers(All<Transform>(scene).Single(t=>t.name==MainRoot));EditorSceneManager.MarkSceneDirty(scene);EditorSceneManager.SaveScene(scene);return "Connected all 4 generated garment hangers to the retained suspension hooks";}finally{if(opened)EditorSceneManager.CloseScene(scene,true);SceneManager.SetActiveScene(prev);}}
 static void Shot(Camera camera,string name){typeof(FactoryRoofStairHeadPass).GetMethod("Shot",System.Reflection.BindingFlags.Static|System.Reflection.BindingFlags.NonPublic).Invoke(null,new object[]{camera,name});Directory.CreateDirectory("Captures/FactoryWorkerBase");File.Copy("Captures/FactoryRoofStairHead/"+name+".png","Captures/FactoryWorkerBase/"+name+".png",true);}
 public static string Capture(){if(EditorApplication.isPlayingOrWillChangePlaymode)throw new Exception("Stop play before capture");var prev=SceneManager.GetActiveScene();var scene=SceneManager.GetSceneByPath(ScenePath);bool opened=!scene.isLoaded;if(opened)scene=EditorSceneManager.OpenScene(ScenePath,OpenSceneMode.Additive);var renderers=Object.FindObjectsOfType<Renderer>(true).Where(r=>r.enabled&&r.gameObject.scene!=scene).ToArray();var lights=Object.FindObjectsOfType<Light>(true).Where(l=>l.enabled&&l.gameObject.scene!=scene).ToArray();GameObject cg=null;try{foreach(var r in renderers)r.enabled=false;foreach(var l in lights)l.enabled=false;SceneManager.SetActiveScene(scene);foreach(var w in All<Recoil3DWorld>(scene))w.ApplyAtmosphere();foreach(var look in All<WarehouseAtmosphereTest>(scene))look.ApplyLook();cg=new GameObject("Temporary Meshy bedding review camera");SceneManager.MoveGameObjectToScene(cg,scene);var camera=cg.AddComponent<Camera>();camera.clearFlags=CameraClearFlags.SolidColor;camera.backgroundColor=new Color(.025f,.03f,.03f);camera.nearClipPlane=.1f;camera.farClipPlane=100;camera.fieldOfView=42;camera.transform.position=new Vector3(20f,9.5f,-1.4f);camera.transform.LookAt(new Vector3(20f,9.1f,5.2f));Shot(camera,"Meshy-beds-and-hanging-workwear");camera.transform.position=new Vector3(21.6f,9.75f,1.2f);camera.transform.LookAt(new Vector3(20.1f,9.5f,5.7f));Shot(camera,"Meshy-workwear-side-volume");camera.fieldOfView=45;camera.transform.position=new Vector3(20.9f,8.9f,2.2f);camera.transform.LookAt(new Vector3(19.8f,7.85f,4.7f));Shot(camera,"Meshy-pallet-bedding-thickness");return "Captured full bedding/workwear, angled garment volume and mattress detail with authored scene lighting";}finally{if(cg)Object.DestroyImmediate(cg);foreach(var r in renderers)if(r)r.enabled=true;foreach(var l in lights)if(l)l.enabled=true;if(opened)EditorSceneManager.CloseScene(scene,true);SceneManager.SetActiveScene(prev);foreach(var w in All<Recoil3DWorld>(prev))w.ApplyAtmosphere();foreach(var look in All<WarehouseAtmosphereTest>(prev))look.ApplyLook();}}
}
